/**
 * bookKey 身份（权威）：
 *   bookKey = layout 步坐标 = (docId, page, layoutK)
 *   空间（book+page）第一次被 layout 切成可指称槽时铸门；OCR/改字不是开门。
 *
 * 面上的 T：OCR 初读或人手改正文，挂在门上；同槽改 T / 重 OCR 读数 → 不换 bookKey。
 * 仅 layout 重切（槽集合/序位变）才可能换门。
 *
 * 服务端 lockId 公式（勿改，封印依赖稳定）：
 *   `${docId}|slot|p${page}|k${layoutK}`
 * 浏览器只持 opaque handle；|slot| 为历史词，语义=layout 槽。
 */

export type BookKeyCoord = {
  docId: string
  page: number
  /** 页内 layout 步序（0-based）；≠ OCR 步 */
  layoutK: number
}

/** 与 api/_lib/protocol/keys.makeSlotKey 同构（仅文档/测试用；浏览器禁止自铸门牌） */
export function bookKeyLockIdFormula(c: BookKeyCoord): string {
  return `${c.docId}|slot|p${c.page}|k${c.layoutK}`
}

export const BOOK_KEY_RULE = {
  identity: 'layout' as const,
  face: 'T' as const,
  remintOnTextEdit: false,
  remintOnOcrReread: false,
  remintOnLayoutRecut: true,
} as const

/**
 * Intrinsic doorplate keys — server authority only.
 * Browser must treat lockId as opaque.
 *
 * bookKey lockId = layout 步坐标（非 OCR）：
 *   `${docId}|slot|p${page}|k${layoutK}`
 * |slot| 为历史词；k = layoutK。同槽改 T / 重 OCR 不改 lockId。
 */

export function stableShortHash(input: string): string {
  let h = 2166136261
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return (h >>> 0).toString(36)
}

/** Layout-slot doorplate → bookKey identity (seal this; never hash OCR text). */
export function makeSlotKey(docId: string, page: number, layoutK: number): string {
  return `${docId}|slot|p${page}|k${layoutK}`
}

export function makeComboKey(docId: string, memberKeys: string[]): string {
  const body = [...memberKeys].sort().join('\0')
  return `${docId}|combo|${stableShortHash(body)}`
}

export function makeFigKey(docId: string, figId: string): string {
  return `${docId}|fig|${figId}`
}

