/**
 * Server cut-encode: one layout proposal row → one slot; geom from proposal;
 * T from same row (no client-side rebind).
 */
export async function emitPageSlots(input: {
  docId: string
  page: number
  imageDataUri: string
}): Promise<EmitPageResult> {
  const layout = await callZhipuLayout(input.imageDataUri)
  // Single page image → always page 0 of layout_details
  const blocks = parseLayoutBlocks(layout, 0)
  if (blocks.length === 0) {
    const hint =
      isRecord(layout) && Array.isArray(layout.layout_details)
        ? `layout_details pages=${layout.layout_details.length}`
        : 'no layout_details'
    throw new Error(
      `OCR 未切出任何版面槽（${hint}）。请确认智谱 layout_parsing 返回含 bbox 的块。`,
    )
  }

  const slots: EmittedSlot[] = blocks.map((b, k) => ({
    lockId: makeSlotKey(input.docId, input.page, k),
    slotK: k,
    page: input.page,
    label: b.label,
    bbox: b.bbox,
    content: b.content,
    sourceContent: b.content,
    cutBound: true as const,
  }))

