/**
 * 页上划重点共享基底（权威）：
 *
 * 纯空间：同一份未改版 PDF 的某一页（docId + page）+ page_norm bbox。
 * 时间化划重点（同级 peer）：
 *   - layout(k)   机器划重点 → 铸 bookKey
 *   - emphasize(j) 人手划重点 → 不铸 bookKey；与 layout 取交/命中
 *
 * 两者如同在同一分析对象上画画指物；共指靠同一坐标系，不靠精确墨迹布尔交。
 */

import type { BookKeyCoord } from './bookKey'

export type PageNormBBox = [number, number, number, number]
export type PageNormPoint = [number, number]

export type PageMarkKind = 'layout' | 'emphasize'

/** 一笔划重点（layout 或强调笔）——同级时间事件 */
export type PageMark = {
  markId: string
  kind: PageMarkKind
  docId: string
  /** 页 = strandIndex */
  page: number
  /** 共享几何基底（page_norm 0–1000） */
  aabb: PageNormBBox
  polygon?: PageNormPoint[]
  createdAt: number
  /** layout 专有：步序；铸 bookKey 用 */
  layoutK?: number
  /** layout 铸键后的门牌；emphasize 永不为自己铸 bookKey */
  bookKey?: string
}

export const PAGE_MARK_RULE = {
  substrate: 'docId+page+page_norm_bbox' as const,
  peers: ['layout', 'emphasize'] as const,
  /** bookKey 只从 layout 铸 */
  mintBookKeyFrom: 'layout' as const,
  /** 强调笔默认：与同页 layout 槽做覆盖命中（粗交），不新铸门 */
  emphasizeHitsLayout: true,
  remintBookKeyOnEmphasize: false,
} as const

export function aabbOverlapArea(a: PageNormBBox, b: PageNormBBox): number {
  const x0 = Math.max(a[0], b[0])
  const y0 = Math.max(a[1], b[1])
  const x1 = Math.min(a[2], b[2])
  const y1 = Math.min(a[3], b[3])
  return Math.max(0, x1 - x0) * Math.max(0, y1 - y0)
}

/** 粗交：两框有重叠则返回交区 AABB；无重叠返回 null */
export function aabbIntersection(
  a: PageNormBBox,
  b: PageNormBBox,
): PageNormBBox | null {
  const x0 = Math.max(a[0], b[0])
  const y0 = Math.max(a[1], b[1])
  const x1 = Math.min(a[2], b[2])
  const y1 = Math.min(a[3], b[3])
  if (x1 <= x0 || y1 <= y0) return null
  return [x0, y0, x1, y1]
}

export function layoutMarkId(coord: BookKeyCoord): string {
  return `mark_layout_p${coord.page}_k${coord.layoutK}`
}

export function makeLayoutPageMark(input: {
  docId: string
  page: number
  layoutK: number
  aabb: PageNormBBox
  bookKey: string
  createdAt?: number
}): PageMark {
  const coord = {
    docId: input.docId,
    page: input.page,
    layoutK: input.layoutK,
  }
  return {
    markId: layoutMarkId(coord),
    kind: 'layout',
    docId: input.docId,
    page: input.page,
    aabb: input.aabb,
    layoutK: input.layoutK,
    bookKey: input.bookKey,
    createdAt: input.createdAt ?? Date.now(),
  }
}

export function makeEmphasizePageMark(input: {
  markId: string
  docId: string
  page: number
  aabb: PageNormBBox
  polygon?: PageNormPoint[]
  createdAt?: number
}): PageMark {
  return {
    markId: input.markId,
    kind: 'emphasize',
    docId: input.docId,
    page: input.page,
    aabb: input.aabb,
    polygon: input.polygon,
    createdAt: input.createdAt ?? Date.now(),
  }
}

/**
 * bookKey 身份（权威）：
 *   bookKey = layout 划重点铸键 = (docId, page, layoutK)
 *   与强调笔共享页上基底（见 pageMark.ts）；OCR/改字不是开门。
 *
 * 面上的 T：OCR 初读或人手改正文，挂在门上；同槽改 T / 重 OCR → 不换 bookKey。
 * 仅 layout 重切（槽集合/序位变）才可能换门。
 *
 * 服务端 lockId 公式（勿改，封印依赖稳定）：
 *   `${docId}|slot|p${page}|k${layoutK}`
 * 浏览器只持 opaque handle；|slot| 为历史词，语义=layout 槽。
 */

export type BookKeyCoord = {
  docId: string
  page: number
  /** 页内 layout 步序（0-based）；≠ OCR 步 */
  layoutK: number
}

/** 与 api/_lib/protocol/keys.makeSlotKey 同构（仅文档/测试用；浏览器禁止自铸门牌） */
export function bookKeyLockIdFormula(c: BookKeyCoord): string {
  return `${c.docId}|slot|p${c.page}|k${c.layoutK}`
}

export const BOOK_KEY_RULE = {
  identity: 'layout' as const,
  /** 铸键动作：layout 提案 → seal（与 desk settle 同属「铸键」，公式不同） */
  mint: 'seal_layout_coord' as const,
  face: 'T' as const,
  remintOnTextEdit: false,
  remintOnOcrReread: false,
  remintOnLayoutRecut: true,
  /** 强调笔命中不换/不铸 bookKey */
  remintOnEmphasizeHit: false,
} as const

/**
 * 页划重点登记表：layout（机器）与 emphasize（人手）同级 peer。
 * bookKey 只出现在 layout 标记上；强调笔经交/命中接到 layout 门牌。
 */

import { create } from 'zustand'
import {
  makeEmphasizePageMark,
  makeLayoutPageMark,
  type PageMark,
  type PageNormBBox,
  type PageNormPoint,
} from '../arch/pageMark'
import type { BookIndex } from './pipelineA'

type PageMarkState = {
  /** docId → marks（layout + emphasize） */
  byDoc: Record<string, PageMark[]>
  /** 最近一次强调∩layout 命中的 bookKey（供 peek/窗选） */
  lastHitBookKeys: string[]
  lastHitDocId: string | null
  lastHitEmphasisId: string | null

  syncLayoutFromBookIndex: (index: BookIndex) => void
  upsertEmphasizeMark: (input: {
    markId: string
    docId: string
    page: number
    aabb: PageNormBBox
    polygon?: PageNormPoint[]
    createdAt?: number
  }) => void
  removeMark: (docId: string, markId: string) => void
  clearDoc: (docId: string) => void
  listMarks: (docId: string, kind?: PageMark['kind']) => PageMark[]
  setLastLayoutHits: (input: {
    docId: string
    emphasisId: string
    bookKeys: string[]
  }) => void
  clearLastHits: () => void
}

export const usePageMarkStore = create<PageMarkState>((set, get) => ({
  byDoc: {},
  lastHitBookKeys: [],
  lastHitDocId: null,
  lastHitEmphasisId: null,

  syncLayoutFromBookIndex: (index) => {
    const layoutMarks = index.chunks.map((c) =>
      makeLayoutPageMark({
        docId: index.docId,
        page: c.page,
        layoutK: c.layoutK ?? c.slotK,
        aabb: c.bbox,
        bookKey: c.key,
        createdAt: index.builtAt,
      }),
    )
    set((s) => {
      const prev = s.byDoc[index.docId] ?? []
      const emphasize = prev.filter((m) => m.kind === 'emphasize')
      return {
        byDoc: {
          ...s.byDoc,
          [index.docId]: [...layoutMarks, ...emphasize],
        },
      }
    })
  },

  upsertEmphasizeMark: (input) => {
    const mark = makeEmphasizePageMark(input)
    set((s) => {
      const prev = s.byDoc[input.docId] ?? []
      const without = prev.filter((m) => m.markId !== mark.markId)
      return {
        byDoc: {
          ...s.byDoc,
          [input.docId]: [...without, mark],
        },
      }
    })
  },

  removeMark: (docId, markId) => {
    set((s) => {
      const prev = s.byDoc[docId] ?? []
      return {
        byDoc: {
          ...s.byDoc,
          [docId]: prev.filter((m) => m.markId !== markId),
        },
      }
    })
  },

  clearDoc: (docId) => {
    set((s) => {
      const next = { ...s.byDoc }
      delete next[docId]
      return { byDoc: next }
    })
  },

  listMarks: (docId, kind) => {
    const all = get().byDoc[docId] ?? []
    return kind ? all.filter((m) => m.kind === kind) : all
  },

  setLastLayoutHits: ({ docId, emphasisId, bookKeys }) => {
    set({
      lastHitDocId: docId,
      lastHitEmphasisId: emphasisId,
      lastHitBookKeys: [...new Set(bookKeys.filter(Boolean))],
    })
  },

  clearLastHits: () =>
    set({
      lastHitBookKeys: [],
      lastHitDocId: null,
      lastHitEmphasisId: null,
    }),
}))

