/**
 * 强调笔 ∩ layout：同一 doc/page 上，用人手划重点命中机器划重点槽。
 * 返回带 score 的 A1 原子（bookKey = chunk.key）；不新铸 bookKey。
 */
export function intersectEmphasizeWithLayout(
  index: BookIndex,
  edge: EmphasisEdge,
): {
  textHits: Array<AChunk & { score: number }>
  figHits: Array<AChunk & { score: number }>
  bookKeys: string[]
} {
  const pageChunks = index.chunks.filter((c) => c.page === edge.strandIndex)
  const textHits: Array<AChunk & { score: number }> = []
  const figHits: Array<AChunk & { score: number }> = []
  for (const chunk of pageChunks) {
    const { hit, score } = chunkHitScore(chunk.bbox, edge.region)
    if (!hit) continue
    if (chunk.kind === 'text') textHits.push({ ...chunk, score })
    else figHits.push({ ...chunk, score })
  }
  const primary = textHits.length > 0 ? textHits : figHits
  const bookKeys = [...new Set(primary.map((c) => c.key).filter(Boolean))]
  return { textHits, figHits, bookKeys }
}

/**
 * 圈选 → 位置锁：强调笔与 layout 同级共指；命中已有 bookKey（layout 铸），
 * 多槽连续命中可 mint combo（B-side，不写回 A1）。
 */
export async function resolveCircleToR(
  edge: EmphasisEdge,
  index: BookIndex,
): Promise<CircleResolveResult> {
  // 同分析对象：edge.docId 有则须与 index 一致
  if (edge.docId && edge.docId !== index.docId) {
    return {
      ok: false,
      reason: 'no_chunks',
      message: `强调笔 docId=${edge.docId} 与书索引 ${index.docId} 不一致（须同一份 PDF）。`,
    }
  }

  const pageChunks = index.chunks.filter((c) => c.page === edge.strandIndex)
  if (pageChunks.length === 0) {
    return {
      ok: false,
      reason: 'no_chunks',
      message:
        '本页尚无 layout 划重点（A1/bookKey）。请先 emit/OCR；扫描无字页应已登记图脸。',
    }
  }

  const { textHits, figHits } = intersectEmphasizeWithLayout(index, edge)
  const primaryHits = textHits.length > 0 ? textHits : figHits
  if (primaryHits.length === 0) {
    return {
      ok: false,
      reason: 'no_hit',
      message:
        '强调笔未与本页任何 layout 槽相交。请圈在已切块的文字/图区上（共享 page_norm bbox）。',
    }
  }

  const runs = contiguousRuns(primaryHits)
  const candidates = (
    await Promise.all(
      runs.map((run) => atomToCandidate(index.docId, run, edge.id)),
    )
  ).sort((a, b) => b.score - a.score)

  // 登记命中：供 peek 窗 / 下游用 layout bookKey，不经 emphasize id
  try {
    const { usePageMarkStore } = await import('./pageMarkStore')
    usePageMarkStore.getState().setLastLayoutHits({
      docId: index.docId,
      emphasisId: edge.id,
      bookKeys: primaryHits.map((c) => c.key),
    })
  } catch {
    /* store optional at build */
  }

  return {
    ok: true,
    chosen: candidates[0],
    candidates,
    source: primaryHits[0].source,
  }
}

