  if (!trimmed) return null
  const now = Date.now()
  const id = newBondId()
  const bond: PermanentBond = {
    id,
    strandIndex: ocrActiveStrand,
    bbox: [...block.bbox] as [number, number, number, number],
    ocrBlockId: block.id,
    confirmedText: block.content,
    comment: trimmed,
    createdAt: now,
    updatedAt: now,
  }
  applyBondGraph(set, get, [...permanentBonds, bond], userBeams)
  return id
},

