/**
 * 页上划重点共享基底（权威）：
 *
 * 纯空间：同一份未改版 PDF 的某一页（docId + page）+ page_norm bbox。
 * 时间化划重点 —— layout 与 emphasize **同级 peer**：
 *   都是在同一分析对象上画画指位置；都能成为铸 bookKey 的提案。
 *
 * 铸键不对称的是「谁默信提案」：
 *   - layout(k)     机器切块 → 系统默信 → 直接铸 bookKey
 *   - emphasize(j)  人手圈画 → 与 layout 粗交命中已有门；
 *                   **未覆盖区**须用户确认后，才按 layout 同公式铸新 bookKey
 *
 * 只有「未覆盖也可经确认开门」，二者才真正同级；否则强调笔只是 layout 的附属命中器。
 */

import type { BookKeyCoord } from './bookKey'

export type PageNormBBox = [number, number, number, number]
export type PageNormPoint = [number, number]

export type PageMarkKind = 'layout' | 'emphasize'

/** 一笔划重点（layout 或强调笔）——同级时间事件 */
export type PageMark = {
  markId: string
  kind: PageMarkKind
  docId: string
  /** 页 = strandIndex */
  page: number
  /** 共享几何基底（page_norm 0–1000） */
  aabb: PageNormBBox
  polygon?: PageNormPoint[]
  createdAt: number
  /** 铸门后的 layout 步序（layout 自带；emphasize 确认铸键后写入） */
  layoutK?: number
  /**
   * 铸成的 bookKey。
   * layout：emit 时即有；emphasize：仅用户确认铸键后才有。
   */
  bookKey?: string
}

/** 强调笔相对 layout 覆盖的判定 */
export type EmphasizeCoverage =
  | 'hit_existing'
  | 'uncovered_needs_confirm'
  | 'mixed_hit_and_uncovered'

export const PAGE_MARK_RULE = {
  substrate: 'docId+page+page_norm_bbox' as const,
  peers: ['layout', 'emphasize'] as const,
  /** 门牌公式统一走 layout 坐标 seal；谁提案不同 */
  mintFormula: 'layout_coord_seal' as const,
  /** layout 提案：系统默信并铸门 */
  layoutAutoMint: true,
  /** emphasize 命中已有 layout → 复用 bookKey，不重铸 */
  emphasizeHitsLayout: true,
  /** emphasize 未覆盖区 → 必须用户确认才铸新 bookKey */
  emphasizeUncoveredNeedsConfirm: true,
  remintBookKeyOnEmphasizeStroke: false,
} as const

export function aabbOverlapArea(a: PageNormBBox, b: PageNormBBox): number {
  const x0 = Math.max(a[0], b[0])
  const y0 = Math.max(a[1], b[1])
  const x1 = Math.min(a[2], b[2])
  const y1 = Math.min(a[3], b[3])
  return Math.max(0, x1 - x0) * Math.max(0, y1 - y0)
}

/** 粗交：两框有重叠则返回交区 AABB；无重叠返回 null */
export function aabbIntersection(
  a: PageNormBBox,
  b: PageNormBBox,
): PageNormBBox | null {
  const x0 = Math.max(a[0], b[0])
  const y0 = Math.max(a[1], b[1])
  const x1 = Math.min(a[2], b[2])
  const y1 = Math.min(a[3], b[3])
  if (x1 <= x0 || y1 <= y0) return null
  return [x0, y0, x1, y1]
}

export function layoutMarkId(coord: BookKeyCoord): string {
  return `mark_layout_p${coord.page}_k${coord.layoutK}`
}

export function makeLayoutPageMark(input: {
  docId: string
  page: number
  layoutK: number
  aabb: PageNormBBox
  bookKey: string
  createdAt?: number
}): PageMark {
  const coord = {
    docId: input.docId,
    page: input.page,
    layoutK: input.layoutK,
  }
  return {
    markId: layoutMarkId(coord),
    kind: 'layout',
    docId: input.docId,
    page: input.page,
    aabb: input.aabb,
    layoutK: input.layoutK,
    bookKey: input.bookKey,
    createdAt: input.createdAt ?? Date.now(),
  }
}

export function makeEmphasizePageMark(input: {
  markId: string
  docId: string
  page: number
  aabb: PageNormBBox
  polygon?: PageNormPoint[]
  createdAt?: number
  /** 用户确认铸键后填入 */
  bookKey?: string
  layoutK?: number
}): PageMark {
  return {
    markId: input.markId,
    kind: 'emphasize',
    docId: input.docId,
    page: input.page,
    aabb: input.aabb,
    polygon: input.polygon,
    createdAt: input.createdAt ?? Date.now(),
    bookKey: input.bookKey,
    layoutK: input.layoutK,
  }
}

