/**
 * 强调笔 ∩ layout：命中已有门则复用 bookKey；未命中不在此铸键（须用户确认）。
 */
export function intersectEmphasizeWithLayout(
  index: BookIndex,
  edge: EmphasisEdge,
): {
  textHits: Array<AChunk & { score: number }>
  figHits: Array<AChunk & { score: number }>
  bookKeys: string[]
  coverage: 'hit_existing' | 'uncovered_needs_confirm'
} {
  const pageChunks = index.chunks.filter((c) => c.page === edge.strandIndex)
  const textHits: Array<AChunk & { score: number }> = []
  const figHits: Array<AChunk & { score: number }> = []
  for (const chunk of pageChunks) {
    const { hit, score } = chunkHitScore(chunk.bbox, edge.region)
    if (!hit) continue
    if (chunk.kind === 'text') textHits.push({ ...chunk, score })
    else figHits.push({ ...chunk, score })
  }
  const primary = textHits.length > 0 ? textHits : figHits
  const bookKeys = [...new Set(primary.map((c) => c.key).filter(Boolean))]
  return {
    textHits,
    figHits,
    bookKeys,
    coverage:
      bookKeys.length > 0 ? 'hit_existing' : 'uncovered_needs_confirm',
  }
}

/**
 * 圈选 → 共指：
 * - 命中 layout → 拿到已有 bookKey（同级复用）
 * - 未覆盖 → uncovered_needs_confirm（同级：等人手确认再铸门）
 */
export async function resolveCircleToR(
  edge: EmphasisEdge,
  index: BookIndex,
): Promise<CircleResolveResult> {
  if (edge.docId && edge.docId !== index.docId) {
    return {
      ok: false,
      reason: 'no_chunks',
      message: `强调笔 docId=${edge.docId} 与书索引 ${index.docId} 不一致（须同一份 PDF）。`,
    }
  }

  const docId = index.docId
  const pendingConfirm = {
    emphasizeId: edge.id,
    docId,
    page: edge.strandIndex,
    aabb: [...edge.region.aabb] as [number, number, number, number],
  }

  const pageChunks = index.chunks.filter((c) => c.page === edge.strandIndex)
  if (pageChunks.length === 0) {
    try {
      const { usePageMarkStore } = await import('./pageMarkStore')
      usePageMarkStore.getState().setPendingEmphasizeConfirm(pendingConfirm)
    } catch {
      /* optional */
    }
    return {
      ok: false,
      reason: 'uncovered_needs_confirm',
      message:
        '本页尚无 layout 槽。强调笔与 layout 同级：请确认后将此圈铸为新 bookKey。',
      pendingConfirm,
    }
  }

  const { textHits, figHits, coverage } = intersectEmphasizeWithLayout(
    index,
    edge,
  )
  const primaryHits = textHits.length > 0 ? textHits : figHits
  if (primaryHits.length === 0 || coverage === 'uncovered_needs_confirm') {
    try {
      const { usePageMarkStore } = await import('./pageMarkStore')
      usePageMarkStore.getState().setPendingEmphasizeConfirm(pendingConfirm)
    } catch {
      /* optional */
    }
    return {
      ok: false,
      reason: 'uncovered_needs_confirm',
      message:
        '强调笔未盖住任何 layout 槽（layout 未覆盖此处）。同级：确认后铸新 bookKey；勿把强调笔当成只能点已有门。',
      pendingConfirm,
    }
  }

  const runs = contiguousRuns(primaryHits)
  const candidates = (
    await Promise.all(
