/**
 * 页划重点登记表：layout（机器）与 emphasize（人手）同级 peer。
 * - 命中已有 layout → 复用 bookKey
 * - 未覆盖 → pendingConfirm，用户确认后铸新 bookKey（同 layout 公式）
 */

import { create } from 'zustand'
import {
  makeEmphasizePageMark,
  makeLayoutPageMark,
  type PageMark,
  type PageNormBBox,
  type PageNormPoint,
} from '../arch/pageMark'
import type { BookIndex } from './pipelineA'

export type PendingEmphasizeConfirm = {
  emphasizeId: string
  docId: string
  page: number
  aabb: PageNormBBox
}

type PageMarkState = {
  byDoc: Record<string, PageMark[]>
  lastHitBookKeys: string[]
  lastHitDocId: string | null
  lastHitEmphasisId: string | null
  pendingEmphasizeConfirm: PendingEmphasizeConfirm | null

  syncLayoutFromBookIndex: (index: BookIndex) => void
  upsertEmphasizeMark: (input: {
    markId: string
    docId: string
    page: number
    aabb: PageNormBBox
    polygon?: PageNormPoint[]
    createdAt?: number
    bookKey?: string
    layoutK?: number
  }) => void
  /** 确认铸键后：强调笔 mark 挂上 bookKey，并登记对应 layout mark */
  attachBookKeyToEmphasize: (input: {
    docId: string
    emphasizeId: string
    bookKey: string
    layoutK: number
    aabb: PageNormBBox
  }) => void
  removeMark: (docId: string, markId: string) => void
  clearDoc: (docId: string) => void
  listMarks: (docId: string, kind?: PageMark['kind']) => PageMark[]
  setLastLayoutHits: (input: {
    docId: string
    emphasisId: string
    bookKeys: string[]
  }) => void
  clearLastHits: () => void
  setPendingEmphasizeConfirm: (p: PendingEmphasizeConfirm | null) => void
  clearPendingEmphasizeConfirm: () => void
}

export const usePageMarkStore = create<PageMarkState>((set, get) => ({
  byDoc: {},
  lastHitBookKeys: [],
  lastHitDocId: null,
  lastHitEmphasisId: null,
  pendingEmphasizeConfirm: null,

  syncLayoutFromBookIndex: (index) => {
    const layoutMarks = index.chunks.map((c) =>
      makeLayoutPageMark({
        docId: index.docId,
        page: c.page,
        layoutK: c.layoutK ?? c.slotK,
        aabb: c.bbox,
        bookKey: c.key,
        createdAt: index.builtAt,
      }),
    )
    set((s) => {
      const prev = s.byDoc[index.docId] ?? []
      const emphasize = prev.filter((m) => m.kind === 'emphasize')
      return {
        byDoc: {
          ...s.byDoc,
          [index.docId]: [...layoutMarks, ...emphasize],
        },
      }
    })
  },

  upsertEmphasizeMark: (input) => {
    const mark = makeEmphasizePageMark(input)
    set((s) => {
      const prev = s.byDoc[input.docId] ?? []
      const without = prev.filter((m) => m.markId !== mark.markId)
      return {
        byDoc: {
          ...s.byDoc,
          [input.docId]: [...without, mark],
        },
      }
    })
  },

  attachBookKeyToEmphasize: ({
    docId,
    emphasizeId,
    bookKey,
    layoutK,
    aabb,
  }) => {
    set((s) => {
      const prev = s.byDoc[docId] ?? []
      const next = prev.map((m) =>
        m.markId === emphasizeId && m.kind === 'emphasize'
          ? { ...m, bookKey, layoutK }
          : m,
      )
      const hasLayout = next.some(
        (m) => m.kind === 'layout' && m.bookKey === bookKey,
      )
      const withLayout = hasLayout
        ? next
        : [
            ...next,
            makeLayoutPageMark({
              docId,
              page:
                next.find((m) => m.markId === emphasizeId)?.page ??
                s.pendingEmphasizeConfirm?.page ??
                0,
              layoutK,
              aabb,
              bookKey,
            }),
          ]
      return {
        byDoc: { ...s.byDoc, [docId]: withLayout },
        lastHitDocId: docId,
        lastHitEmphasisId: emphasizeId,
        lastHitBookKeys: [bookKey],
        pendingEmphasizeConfirm: null,
      }
    })
  },

  removeMark: (docId, markId) => {
    set((s) => {
      const prev = s.byDoc[docId] ?? []
      return {
        byDoc: {
          ...s.byDoc,
          [docId]: prev.filter((m) => m.markId !== markId),
        },
        pendingEmphasizeConfirm:
          s.pendingEmphasizeConfirm?.emphasizeId === markId
            ? null
            : s.pendingEmphasizeConfirm,
      }
    })
  },

  clearDoc: (docId) => {
    set((s) => {
      const next = { ...s.byDoc }
      delete next[docId]
      return {
        byDoc: next,
        pendingEmphasizeConfirm:
          s.pendingEmphasizeConfirm?.docId === docId
            ? null
            : s.pendingEmphasizeConfirm,
      }
    })
  },

  listMarks: (docId, kind) => {
    const all = get().byDoc[docId] ?? []
    return kind ? all.filter((m) => m.kind === kind) : all
  },

  setLastLayoutHits: ({ docId, emphasisId, bookKeys }) => {
    set({
      lastHitDocId: docId,
      lastHitEmphasisId: emphasisId,
      lastHitBookKeys: [...new Set(bookKeys.filter(Boolean))],
    })
  },

  clearLastHits: () =>
    set({
      lastHitBookKeys: [],
      lastHitDocId: null,
      lastHitEmphasisId: null,
    }),

  setPendingEmphasizeConfirm: (p) => set({ pendingEmphasizeConfirm: p }),
  clearPendingEmphasizeConfirm: () => set({ pendingEmphasizeConfirm: null }),
}))

/**
 * 强调笔未覆盖区 → 用户确认 → 铸 bookKey（与 layout 同公式、同级）。
 */

import type { EmphasisEdge } from '../data/emphasis'
import {
  appendConfirmedLayoutSlotFromEmphasize,
  type BookIndex,
} from './pipelineA'
import { usePageMarkStore } from './pageMarkStore'
import { useIndexGate } from './indexGate'

export type ConfirmEmphasizeMintResult =
  | {
      ok: true
      bookKey: string
      layoutK: number
      index: BookIndex
      note: string
    }
  | { ok: false; note: string }

/**
 * 必须显式 confirm=true（人手确认）。
 * 命中已有 layout 时不应走此路径（resolveCircle 已复用门牌）。
 */
export async function confirmEmphasizeMintBookKey(input: {
  edge: EmphasisEdge
  bookIndex: BookIndex
  /** 必须为 true，防止误铸 */
  confirm: true
  content?: string
}): Promise<ConfirmEmphasizeMintResult> {
  if (input.confirm !== true) {
    return { ok: false, note: '须用户确认（confirm:true）才可铸门' }
  }
  try {
    const { index, bookKey, layoutK, note } =
      await appendConfirmedLayoutSlotFromEmphasize({
        index: input.bookIndex,
        edge: input.edge,
        content: input.content,
      })
    useIndexGate.getState().setBookIndex(index, true)
    usePageMarkStore.getState().attachBookKeyToEmphasize({
      docId: index.docId,
      emphasizeId: input.edge.id,
      bookKey,
      layoutK,
      aabb: input.edge.region.aabb,
    })
    return { ok: true, bookKey, layoutK, index, note }
  } catch (e) {
    return {
      ok: false,
      note: e instanceof Error ? e.message : String(e),
    }
  }
}

/** 从 pageMarkStore.pending 取边所需最小信息时，用 emphasisEdges 找回完整 edge 再调上面 */
export async function confirmPendingEmphasizeMint(input: {
  edge: EmphasisEdge
  confirm: true
  content?: string
}): Promise<ConfirmEmphasizeMintResult> {
  const bookIndex = useIndexGate.getState().bookIndex
  if (!bookIndex) {
    return { ok: false, note: '尚无 BookIndex，无法铸门' }
  }
  const pending = usePageMarkStore.getState().pendingEmphasizeConfirm
  if (!pending || pending.emphasizeId !== input.edge.id) {
    return {
      ok: false,
      note: '无匹配的 pending 未覆盖确认（请先 resolveCircle 得到 uncovered_needs_confirm）',
    }
  }
  return confirmEmphasizeMintBookKey({
    edge: input.edge,
    bookIndex,
    confirm: true,
    content: input.content,
  })
}

