import type { EmphasisEdge, PagePoint, RegionSelector } from '../data/emphasis'
import {
  decomposeEmphasizeAabbAgainstLayout,
  type EmphasizeAabbDecomposition,
} from '../arch/pageMark'

/**
 * 强调笔相对本页 layout/bookKey 的 AABB 分解：
 *   E = ⋃ (E ∩ B_i)  ∪  blank
 */
export function decomposeEmphasizeAgainstLayout(
  index: BookIndex,
  edge: EmphasisEdge,
): EmphasizeAabbDecomposition {
  const pageChunks = index.chunks.filter((c) => c.page === edge.strandIndex)
  return decomposeEmphasizeAabbAgainstLayout(
    edge.region.aabb,
    pageChunks.map((c) => ({
      bookKey: c.key,
      aabb: c.bbox,
      layoutK: c.layoutK ?? c.slotK,
    })),
  )
}

/**
 * 强调笔 ∩ layout（含分解）：命中复用门；空白须确认铸门。
 */
export function intersectEmphasizeWithLayout(
  index: BookIndex,
  edge: EmphasisEdge,
): {
  textHits: Array<AChunk & { score: number }>
  figHits: Array<AChunk & { score: number }>
  bookKeys: string[]
  coverage: EmphasizeAabbDecomposition['coverage']
  decomposition: EmphasizeAabbDecomposition
} {
  const decomposition = decomposeEmphasizeAgainstLayout(index, edge)
  const pieceKeys = new Set(decomposition.onBookKeys.map((p) => p.bookKey))

  const pageChunks = index.chunks.filter((c) => c.page === edge.strandIndex)
  const textHits: Array<AChunk & { score: number }> = []
  const figHits: Array<AChunk & { score: number }> = []
  for (const chunk of pageChunks) {
    if (!pieceKeys.has(chunk.key)) continue
    const piece = decomposition.onBookKeys.find((p) => p.bookKey === chunk.key)
    const score = piece?.fracOfEmphasize ?? 0
    // 仍用原 hit 启发做排序辅助；占块已由分解给出
    const { hit, score: hitScore } = chunkHitScore(chunk.bbox, edge.region)
    const s = hit ? Math.max(score, hitScore) : score
    if (chunk.kind === 'text') textHits.push({ ...chunk, score: s })
    else figHits.push({ ...chunk, score: s })
  }
  const bookKeys = decomposition.onBookKeys.map((p) => p.bookKey)
  return {
    textHits,
    figHits,
    bookKeys,
    coverage: decomposition.coverage,
    decomposition,
  }
}

/**
 * 圈选 → 共指分解：
 * - 纯命中 → 复用 bookKey
 * - 纯空白 → uncovered_needs_confirm（空白=整圈）
 * - mixed → 复用占块门 + 空白 pendingConfirm（铸门几何=blankUnionAabb）
 */
export async function resolveCircleToR(
  edge: EmphasisEdge,
  index: BookIndex,
): Promise<CircleResolveResult> {
  if (edge.docId && edge.docId !== index.docId) {
    return {
      ok: false,
      reason: 'no_chunks',
      message: `强调笔 docId=${edge.docId} 与书索引 ${index.docId} 不一致（须同一份 PDF）。`,
    }
  }

  const docId = index.docId
  const {
    textHits,
    figHits,
    coverage,
    decomposition,
  } = intersectEmphasizeWithLayout(index, edge)

  const blankPending =
    decomposition.blankUnionAabb != null
      ? {
          emphasizeId: edge.id,
          docId,
          page: edge.strandIndex,
          aabb: [...decomposition.blankUnionAabb] as [
            number,
            number,
            number,
            number,
          ],
        }
      : {
          emphasizeId: edge.id,
          docId,
          page: edge.strandIndex,
          aabb: [...edge.region.aabb] as [number, number, number, number],
        }

  if (coverage === 'uncovered_needs_confirm') {
    try {
      const { usePageMarkStore } = await import('./pageMarkStore')
      usePageMarkStore.getState().setPendingEmphasizeConfirm(blankPending)
    } catch {
      /* optional */
    }
    return {
      ok: false,
      reason: 'uncovered_needs_confirm',
      message:
        '强调笔未盖住任何 bookKey 槽。空白即整圈；确认后铸新 bookKey（几何=强调 aabb）。',
      decomposition,
      pendingConfirm: blankPending,
    }
  }

  const primaryHits = textHits.length > 0 ? textHits : figHits
  if (primaryHits.length === 0) {
    try {
      const { usePageMarkStore } = await import('./pageMarkStore')
      usePageMarkStore.getState().setPendingEmphasizeConfirm(blankPending)
    } catch {
      /* optional */
    }
    return {
      ok: false,
      reason: 'uncovered_needs_confirm',
      message: '分解无占块。请确认空白铸门。',
      decomposition,
      pendingConfirm: blankPending,
    }
  }

  const runs = contiguousRuns(primaryHits)
  const candidates = (
    await Promise.all(
      runs.map((run) => atomToCandidate(index.docId, run, edge.id)),
    )
  ).sort((a, b) => b.score - a.score)

  try {
    const { usePageMarkStore } = await import('./pageMarkStore')
    const st = usePageMarkStore.getState()
    st.setLastLayoutHits({
      docId: index.docId,
      emphasisId: edge.id,
      bookKeys: primaryHits.map((c) => c.key),
    })
    if (coverage === 'mixed_hit_and_uncovered') {
      st.setPendingEmphasizeConfirm(blankPending)
    } else {
      st.clearPendingEmphasizeConfirm()
    }
  } catch {
    /* optional */
  }

  return {
    ok: true,
    chosen: candidates[0],
    candidates,
    source: primaryHits[0].source,
    coverage:
      coverage === 'mixed_hit_and_uncovered'
        ? 'mixed_hit_and_uncovered'
        : 'hit_existing',
    decomposition,
    pendingConfirm:
      coverage === 'mixed_hit_and_uncovered' ? blankPending : undefined,
  }
}

