      emphasisId: edge.id,
      bookKeys: primaryHits.map((c) => c.key),
    })
  } catch {
    /* store optional at build */
  }

  return {
    ok: true,
    chosen: candidates[0],
    candidates,
    source: primaryHits[0].source,
    coverage: 'hit_existing',
  }
}

