/**
 * 页划重点登记表：layout（机器）与 emphasize（人手）同级 peer。
 * 占块只指针；仅空白可铸；区域把手 = regionKey（combo 或单门）。
 */

import { create } from 'zustand'
import {
  makeEmphasizePageMark,
  makeLayoutPageMark,
  type PageMark,
  type PageNormBBox,
  type PageNormPoint,
} from '../arch/pageMark'
import type { BookIndex } from './pipelineA'

export type PendingEmphasizeConfirm = {
  emphasizeId: string
  docId: string
  page: number
  aabb: PageNormBBox
}

type PageMarkState = {
  byDoc: Record<string, PageMark[]>
  lastHitBookKeys: string[]
  lastHitDocId: string | null
  lastHitEmphasisId: string | null
  pendingEmphasizeConfirm: PendingEmphasizeConfirm | null

  syncLayoutFromBookIndex: (index: BookIndex) => void
  upsertEmphasizeMark: (input: {
    markId: string
    docId: string
    page: number
    aabb: PageNormBBox
    polygon?: PageNormPoint[]
    createdAt?: number
    bookKey?: string
    layoutK?: number
    regionKey?: string
    regionMemberKeys?: string[]
  }) => void
  /** 空白铸门后：挂 blank bookKey + layout mark */
  attachBookKeyToEmphasize: (input: {
    docId: string
    emphasizeId: string
    bookKey: string
    layoutK: number
    aabb: PageNormBBox
  }) => void
  /** 挂区域把手（指针 combo 或 指针∪空白 combo） */
  attachRegionToEmphasize: (input: {
    docId: string
    emphasizeId: string
    regionKey: string
    regionMemberKeys: string[]
  }) => void
  removeMark: (docId: string, markId: string) => void
  clearDoc: (docId: string) => void
  listMarks: (docId: string, kind?: PageMark['kind']) => PageMark[]
  setLastLayoutHits: (input: {
    docId: string
    emphasisId: string
    bookKeys: string[]
  }) => void
  clearLastHits: () => void
  setPendingEmphasizeConfirm: (p: PendingEmphasizeConfirm | null) => void
  clearPendingEmphasizeConfirm: () => void
}

export const usePageMarkStore = create<PageMarkState>((set, get) => ({
  byDoc: {},
  lastHitBookKeys: [],
  lastHitDocId: null,
  lastHitEmphasisId: null,
  pendingEmphasizeConfirm: null,

  syncLayoutFromBookIndex: (index) => {
    const layoutMarks = index.chunks.map((c) =>
      makeLayoutPageMark({
        docId: index.docId,
        page: c.page,
        layoutK: c.layoutK ?? c.slotK,
        aabb: c.bbox,
        bookKey: c.key,
        createdAt: index.builtAt,
      }),
    )
    set((s) => {
      const prev = s.byDoc[index.docId] ?? []
      const emphasize = prev.filter((m) => m.kind === 'emphasize')
      return {
        byDoc: {
          ...s.byDoc,
          [index.docId]: [...layoutMarks, ...emphasize],
        },
      }
    })
  },

  upsertEmphasizeMark: (input) => {
    const mark = makeEmphasizePageMark(input)
    set((s) => {
      const prev = s.byDoc[input.docId] ?? []
      const without = prev.filter((m) => m.markId !== mark.markId)
      return {
        byDoc: {
          ...s.byDoc,
          [input.docId]: [...without, mark],
        },
      }
    })
  },

  attachBookKeyToEmphasize: ({
    docId,
    emphasizeId,
    bookKey,
    layoutK,
    aabb,
  }) => {
    set((s) => {
      const prev = s.byDoc[docId] ?? []
      const next = prev.map((m) =>
        m.markId === emphasizeId && m.kind === 'emphasize'
          ? { ...m, bookKey, layoutK }
          : m,
      )
      const hasLayout = next.some(
        (m) => m.kind === 'layout' && m.bookKey === bookKey,
      )
      const withLayout = hasLayout
        ? next
        : [
            ...next,
            makeLayoutPageMark({
              docId,
              page:
                next.find((m) => m.markId === emphasizeId)?.page ??
                s.pendingEmphasizeConfirm?.page ??
                0,
              layoutK,
              aabb,
              bookKey,
            }),
          ]
      return {
        byDoc: { ...s.byDoc, [docId]: withLayout },
        lastHitDocId: docId,
        lastHitEmphasisId: emphasizeId,
        lastHitBookKeys: [bookKey],
        pendingEmphasizeConfirm: null,
      }
    })
  },

  attachRegionToEmphasize: ({
    docId,
    emphasizeId,
    regionKey,
    regionMemberKeys,
  }) => {
    set((s) => {
      const prev = s.byDoc[docId] ?? []
      const next = prev.map((m) =>
        m.markId === emphasizeId && m.kind === 'emphasize'
          ? { ...m, regionKey, regionMemberKeys }
          : m,
      )
      return {
        byDoc: { ...s.byDoc, [docId]: next },
        lastHitDocId: docId,
        lastHitEmphasisId: emphasizeId,
        lastHitBookKeys: regionMemberKeys,
      }
    })
  },

  removeMark: (docId, markId) => {
    set((s) => {
      const prev = s.byDoc[docId] ?? []
      return {
        byDoc: {
          ...s.byDoc,
          [docId]: prev.filter((m) => m.markId !== markId),
        },
        pendingEmphasizeConfirm:
          s.pendingEmphasizeConfirm?.emphasizeId === markId
            ? null
            : s.pendingEmphasizeConfirm,
      }
    })
  },

  clearDoc: (docId) => {
    set((s) => {
      const next = { ...s.byDoc }
      delete next[docId]
      return {
        byDoc: next,
        pendingEmphasizeConfirm:
          s.pendingEmphasizeConfirm?.docId === docId
            ? null
            : s.pendingEmphasizeConfirm,
      }
    })
  },

  listMarks: (docId, kind) => {
    const all = get().byDoc[docId] ?? []
    return kind ? all.filter((m) => m.kind === kind) : all
  },

  setLastLayoutHits: ({ docId, emphasisId, bookKeys }) => {
    set({
      lastHitDocId: docId,
      lastHitEmphasisId: emphasisId,
      lastHitBookKeys: bookKeys,
    })
  },

  clearLastHits: () => {
    set({
      lastHitBookKeys: [],
      lastHitDocId: null,
      lastHitEmphasisId: null,
    })
  },

  setPendingEmphasizeConfirm: (p) => set({ pendingEmphasizeConfirm: p }),
  clearPendingEmphasizeConfirm: () => set({ pendingEmphasizeConfirm: null }),
}))

/**
 * 强调笔空白 → 用户确认铸门 → 与指针成员合成 regionKey（combo）。
 */

import type { EmphasisEdge } from '../data/emphasis'
import {
  appendConfirmedLayoutSlotFromEmphasize,
  decomposeEmphasizeAgainstLayout,
  sealEmphasizeRegionKey,
  type BookIndex,
} from './pipelineA'
import { decompositionToRegionBinding } from '../arch/pageMark'
import { usePageMarkStore } from './pageMarkStore'
import { useIndexGate } from './indexGate'

export type ConfirmEmphasizeMintResult =
  | {
      ok: true
      /** 空白新门 */
      bookKey: string
      layoutK: number
      /** 强调笔区域把手 = 指针∪空白 */
      regionKey: string
      regionMemberKeys: string[]
      index: BookIndex
      note: string
    }
  | { ok: false; note: string }

/**
 * 仅空白铸门（confirm:true）。铸完与已有指针合成 regionKey。
 */
export async function confirmEmphasizeMintBookKey(input: {
  edge: EmphasisEdge
  bookIndex: BookIndex
  confirm: true
  content?: string
  mintAabb?: [number, number, number, number]
}): Promise<ConfirmEmphasizeMintResult> {
  if (input.confirm !== true) {
    return { ok: false, note: '须用户确认（confirm:true）才可铸空白门' }
  }
  const pending = usePageMarkStore.getState().pendingEmphasizeConfirm
  const mintAabb =
    input.mintAabb ??
    (pending?.emphasizeId === input.edge.id ? pending.aabb : undefined) ??
    input.edge.region.aabb

  try {
    const { index, bookKey, layoutK, note } =
      await appendConfirmedLayoutSlotFromEmphasize({
        index: input.bookIndex,
        edge: input.edge,
        content: input.content,
        mintAabb,
      })

    const decomposition = decomposeEmphasizeAgainstLayout(index, input.edge)
    // 铸完后 blank 已被新门盖住 → 应用铸前指针 + 新 blank 门封区域
    const bindingBefore = decompositionToRegionBinding(
      decomposeEmphasizeAgainstLayout(input.bookIndex, input.edge),
    )
    const reuseKeys = bindingBefore.reuse.map((r) => r.bookKey)
    const sealed = await sealEmphasizeRegionKey({
      docId: index.docId,
      reuseBookKeys: reuseKeys,
      blankBookKey: bookKey,
    })

    useIndexGate.getState().setBookIndex(index, true)
    const st = usePageMarkStore.getState()
    st.attachBookKeyToEmphasize({
      docId: index.docId,
      emphasizeId: input.edge.id,
      bookKey,
      layoutK,
      aabb: mintAabb,
    })
    st.attachRegionToEmphasize({
      docId: index.docId,
      emphasizeId: input.edge.id,
      regionKey: sealed.regionKey,
      regionMemberKeys: sealed.regionMemberKeys,
    })
    st.clearPendingEmphasizeConfirm()

    return {
      ok: true,
      bookKey,
      layoutK,
      regionKey: sealed.regionKey,
      regionMemberKeys: sealed.regionMemberKeys,
      index,
      note: `${note} · regionKey=${sealed.regionKey.slice(0, 18)}… · members×${sealed.regionMemberKeys.length}`,
    }
  } catch (e) {
    return {
      ok: false,
      note: e instanceof Error ? e.message : String(e),
    }
  }
}

export async function confirmPendingEmphasizeMint(input: {
  edge: EmphasisEdge
  confirm: true
  content?: string
}): Promise<ConfirmEmphasizeMintResult> {
  const bookIndex = useIndexGate.getState().bookIndex
  if (!bookIndex) {
    return { ok: false, note: '尚无 BookIndex，无法铸门' }
  }
  const pending = usePageMarkStore.getState().pendingEmphasizeConfirm
  if (!pending || pending.emphasizeId !== input.edge.id) {
    return {
      ok: false,
      note: '无匹配的 pending 空白确认',
    }
  }
  return confirmEmphasizeMintBookKey({
    edge: input.edge,
    bookIndex,
    confirm: true,
    content: input.content,
    mintAabb: pending.aabb,
  })
}

